// MY_APPROVALS count — access-aware mirror of svc_fetchSubmissions.
const CR = constants.CHANGE_REQUESTS_TABLE;
const GEO_TABLE = constants.GEO_TABLE;
const WS = constants.WS;
const origin = window.location.origin;
const h = { 'Tj-Workspace-Id': WS };
const userEmail = ((globals && globals.currentUser && globals.currentUser.email) || '').toLowerCase();
// Inline access resolution — initAccess runs in parallel via onPageLoad; reading variables.access
// here would race. Resolve fresh from ACCESS_RESOLVER_CODE constant.
let access = variables.access || {};
if (!access || !access.is) {
  try {
    const _src = constants.ACCESS_RESOLVER_CODE;
    if (_src) {
      const _fn = new Function('globals','constants','return (' + _src + ')(globals, constants);');
      access = _fn(globals, constants) || {};
    }
  } catch (e) { console.warn('inline access resolve failed', e && e.message); access = {}; }
}
const isAdmin = !!(access.is && access.is.admin);
const isBuilder = !!(access.is && access.is.builder);
const isChecker = !!(access.is && access.is.checker);
const hasAllDomains = !!access.has_all_domains;
const hasAllGeos = !!access.has_all_geos;
const accessDomains = (Array.isArray(access.domains) ? access.domains : []).map(s => String(s).toLowerCase());
const accessGeos = (Array.isArray(access.geos) ? access.geos : []).map(s => String(s).toLowerCase());

// Gate: maker-only users (no Checker role, no admin/builder) → count=0.
if (!isChecker && !isAdmin && !isBuilder) {
  return { count: 0 };
}

async function resolveDomainNames() {
  if (isAdmin || isBuilder || hasAllDomains) return null;
  if (accessDomains.length === 0) return [];
  const r = await fetch(origin + '/api/tooljet-db/proxy/' + (constants.UTIL_TABLE || '') + '?tj_app_id=not.is.null', { credentials:'include', headers: h });
  let rows = [];
  try { rows = JSON.parse(await r.text()); } catch(_){}
  const allNames = (rows||[]).map(r => r.name).filter(Boolean);
  return allNames.filter(name => accessDomains.includes(String(name).replace(/\\s+/g,'_').toLowerCase()));
}

async function resolveGeoIds() {
  if (isAdmin || isBuilder || hasAllGeos) return null;
  if (accessGeos.length === 0) return [];
  const r = await fetch(origin + '/api/tooljet-db/proxy/' + GEO_TABLE + '?is_active=eq.true', { credentials:'include', headers: h });
  let rows = [];
  try { rows = JSON.parse(await r.text()); } catch(_){}
  const matches = (rows||[]).filter(row => {
    const nm = String(row.display_name || '').replace(/\\s+/g,'_').toLowerCase();
    return accessGeos.includes(nm);
  });
  return matches.map(m => m.geo_region_id).filter(v => v != null);
}

try {
  const params = [
    'status=eq.SUBMITTED',
    'backend_sync_state=eq.SUCCESS',
    'maker_email=neq.' + encodeURIComponent(userEmail || '__none__')
  ];
  const allowedDoms = await resolveDomainNames();
  if (Array.isArray(allowedDoms)) {
    if (allowedDoms.length === 0) return { count: 0 };
    params.push('domain=in.(' + allowedDoms.map(encodeURIComponent).join(',') + ')');
  }
  const allowedGeos = await resolveGeoIds();
  if (Array.isArray(allowedGeos)) {
    if (allowedGeos.length === 0) {
      params.push('geo_region_id=is.null');
    } else {
      params.push('or=(geo_region_id.is.null,geo_region_id.in.(' + allowedGeos.join(',') + '))');
    }
  }
  const hh = Object.assign({}, h, { 'Prefer':'count=exact', 'Range-Unit':'items', 'Range':'0-0' });
  const r = await fetch(origin + '/api/tooljet-db/proxy/' + CR + '?' + params.join('&'), { credentials:'include', headers: hh });
  const range = r.headers.get('content-range') || '';
  const total = parseInt((range.split('/')[1] || '0'), 10);
  return { count: Number.isFinite(total) ? total : 0 };
} catch (e) {
  console.warn('getPendingApprovalsCount failed', e && e.message);
  return { count: 0 };
}
